28	off_t ReadBufferFromEncryptedFile::seek(off_t off, int whence)
29	{
30	    off_t new_pos;
31	    if (whence == SEEK_SET)
32	    {
33	        if (off < 0)
34	            throw Exception("SEEK_SET underflow: off = " + std::to_string(off), ErrorCodes::ARGUMENT_OUT_OF_BOUND);
35	        new_pos = off;
36	    }
37	    else if (whence == SEEK_CUR)
38	    {
39	        if (off < 0 && -off > getPosition())
40	            throw Exception("SEEK_CUR shift out of bounds", ErrorCodes::ARGUMENT_OUT_OF_BOUND);
41	        new_pos = getPosition() + off;
42	    }
43	    else
44	        throw Exception("ReadBufferFromFileEncrypted::seek expects SEEK_SET or SEEK_CUR as whence", ErrorCodes::ARGUMENT_OUT_OF_BOUND);
45	
46	    if ((offset - static_cast<off_t>(working_buffer.size()) <= new_pos) && (new_pos <= offset) && !need_seek)
47	    {
48	        /// Position is still inside buffer.
49	        pos = working_buffer.end() - offset + new_pos;
50	        assert(pos >= working_buffer.begin());
51	        assert(pos <= working_buffer.end());
52	    }
53	    else
54	    {
55	        need_seek = true;
56	        offset = new_pos;
57	
58	        /// No more reading from the current working buffer until next() is called.
59	        resetWorkingBuffer();
60	        assert(!hasPendingData());
61	    }
62	
63	    /// The encryptor always needs to know what the current offset is.
64	    encryptor.setOffset(new_pos);
65	
66	    return new_pos;
67	}
