74	bool ReadBufferFromEncryptedFile::nextImpl()
75	{
76	    if (need_seek)
77	    {
78	        off_t raw_offset = offset + FileEncryption::Header::kSize;
79	        if (in->seek(raw_offset, SEEK_SET) != raw_offset)
80	            return false;
81	        need_seek = false;
82	    }
83	
84	    if (in->eof())
85	        return false;
86	
87	    /// Read up to the size of `encrypted_buffer`.
88	    size_t bytes_read = 0;
89	    while (bytes_read < encrypted_buffer.size() && !in->eof())
90	    {
91	        bytes_read += in->read(encrypted_buffer.data() + bytes_read, encrypted_buffer.size() - bytes_read);
92	    }
93	
94	    /// The used cipher algorithms generate the same number of bytes in output as it were in input,
95	    /// so after deciphering the numbers of bytes will be still `bytes_read`.
96	    working_buffer.resize(bytes_read);
97	    encryptor.decrypt(encrypted_buffer.data(), bytes_read, working_buffer.begin());
98	
99	    offset += bytes_read;
100	    pos = working_buffer.begin();
101	    return true;
102	}
