17	/// Encryption algorithm.
18	/// We chose to use CTR cipther algorithms because they have the following features which are important for us:
19	/// - No right padding, so we can append encrypted files without deciphering;
20	/// - One byte is always ciphered as one byte, so we get random access to encrypted files easily.
21	enum class Algorithm
22	{
23	    AES_128_CTR, /// Size of key is 16 bytes.
24	    AES_192_CTR, /// Size of key is 24 bytes.
25	    AES_256_CTR, /// Size of key is 32 bytes.
26	};
