35	/// Initialization vector. Its size is always 16 bytes.
36	class InitVector
37	{
38	public:
39	    static constexpr const size_t kSize = 16;
40	
41	    InitVector() = default;
42	    explicit InitVector(const UInt128 & counter_) { set(counter_); }
43	
44	    void set(const UInt128 & counter_) { counter = counter_; }
45	    UInt128 get() const { return counter; }
46	
47	    void read(ReadBuffer & in);
48	    void write(WriteBuffer & out) const;
49	
50	    /// Write 16 bytes of the counter to a string in big endian order.
51	    /// We need big endian because the used cipher algorithms treat an initialization vector as a counter in big endian.
52	    String toString() const;
53	
54	    /// Converts a string of 16 bytes length in big endian order to a counter.
55	    static InitVector fromString(const String & str_);
56	
57	    /// Adds a specified offset to the counter.
58	    InitVector & operator++() { ++counter; return *this; }
59	    InitVector operator++(int) { InitVector res = *this; ++counter; return res; } /// NOLINT
60	    InitVector & operator+=(size_t offset) { counter += offset; return *this; }
61	    InitVector operator+(size_t offset) const { InitVector res = *this; return res += offset; }
62	
63	    /// Generates a random initialization vector.
64	    static InitVector random();
65	
66	private:
67	    UInt128 counter = 0;
68	};
