71	/// Encrypts or decrypts data.
72	class Encryptor
73	{
74	public:
75	    /// The `key` should have size 16 or 24 or 32 bytes depending on which `algorithm` is specified.
76	    Encryptor(Algorithm algorithm_, const String & key_, const InitVector & iv_);
77	
78	    /// Sets the current position in the data stream from the very beginning of data.
79	    /// It affects how the data will be encrypted or decrypted because
80	    /// the initialization vector is increased by an index of the current block
81	    /// and the index of the current block is calculated from this offset.
82	    void setOffset(size_t offset_) { offset = offset_; }
83	
84	    /// Encrypts some data.
85	    /// Also the function moves `offset` by `size` (for successive encryptions).
86	    void encrypt(const char * data, size_t size, WriteBuffer & out);
87	
88	    /// Decrypts some data.
89	    /// The used cipher algorithms generate the same number of bytes in output as they were in input,
90	    /// so the function always writes `size` bytes of the plaintext to `out`.
91	    /// Also the function moves `offset` by `size` (for successive decryptions).
92	    void decrypt(const char * data, size_t size, char * out);
93	
94	private:
95	    const String key;
96	    const InitVector init_vector;
97	    const EVP_CIPHER * const evp_cipher;
98	
99	    /// The current position in the data stream from the very beginning of data.
100	    size_t offset = 0;
101	};
