43	    void checkKeySize(const EVP_CIPHER * evp_cipher, size_t key_size)
44	    {
45	        if (!key_size)
46	            throw Exception(ErrorCodes::BAD_ARGUMENTS, "Encryption key must not be empty");
47	        size_t expected_key_size = static_cast<size_t>(EVP_CIPHER_key_length(evp_cipher));
48	        if (key_size != expected_key_size)
49	            throw Exception(
50	                ErrorCodes::BAD_ARGUMENTS, "Got an encryption key with unexpected size {}, the size should be {}", key_size, expected_key_size);
