54	    {
55	        size_t expected_iv_length = static_cast<size_t>(EVP_CIPHER_iv_length(evp_cipher));
56	        if (InitVector::kSize != expected_iv_length)
57	            throw Exception(
58	                ErrorCodes::DATA_ENCRYPTION_ERROR,
