69	    size_t partBlockSize(size_t size, size_t off)
70	    {
71	        assert(off < kBlockSize);
72	        /// write the part as usual block
73	        if (off == 0)
74	            return 0;
75	        return off + size <= kBlockSize ? size : (kBlockSize - off) % kBlockSize;
76	    }
