78	    size_t encryptBlocks(EVP_CIPHER_CTX * evp_ctx, const char * data, size_t size, WriteBuffer & out)
79	    {
80	        const uint8_t * in = reinterpret_cast<const uint8_t *>(data);
81	        size_t in_size = 0;
82	        size_t out_size = 0;
83	
84	        while (in_size < size)
85	        {
86	            out.nextIfAtEnd();
87	            size_t part_size = std::min(size - in_size, out.available());
88	            uint8_t * ciphertext = reinterpret_cast<uint8_t *>(out.position());
89	            int ciphertext_size = 0;
90	            if (!EVP_EncryptUpdate(evp_ctx, ciphertext, &ciphertext_size, &in[in_size], part_size))
91	                throw Exception("Failed to encrypt", ErrorCodes::DATA_ENCRYPTION_ERROR);
92	
93	            in_size += part_size;
94	            if (ciphertext_size)
95	            {
96	                out.position() += ciphertext_size;
97	                out_size += ciphertext_size;
98	            }
99	        }
100	
101	        return out_size;
102	    }
103	
104	    size_t encryptBlockWithPadding(EVP_CIPHER_CTX * evp_ctx, const char * data, size_t size, size_t pad_left, WriteBuffer & out)
105	    {
106	        assert((size <= kBlockSize) && (size + pad_left <= kBlockSize));
107	        uint8_t padded_data[kBlockSize] = {};
108	        memcpy(&padded_data[pad_left], data, size);
109	        size_t padded_data_size = pad_left + size;
110	
111	        uint8_t ciphertext[kBlockSize];
112	        int ciphertext_size = 0;
113	        if (!EVP_EncryptUpdate(evp_ctx, ciphertext, &ciphertext_size, padded_data, padded_data_size))
114	            throw Exception("Failed to encrypt", ErrorCodes::DATA_ENCRYPTION_ERROR);
115	
116	        if (!ciphertext_size)
117	            return 0;
118	
119	        if (static_cast<size_t>(ciphertext_size) < pad_left)
120	            throw Exception(ErrorCodes::DATA_ENCRYPTION_ERROR, "Unexpected size of encrypted data: {} < {}", ciphertext_size, pad_left);
121	
122	        uint8_t * ciphertext_begin = &ciphertext[pad_left];
123	        ciphertext_size -= pad_left;
124	        out.write(reinterpret_cast<const char *>(ciphertext_begin), ciphertext_size);
125	        return ciphertext_size;
126	    }
