128	    size_t encryptFinal(EVP_CIPHER_CTX * evp_ctx, WriteBuffer & out)
129	    {
130	        uint8_t ciphertext[kBlockSize];
131	        int ciphertext_size = 0;
132	        if (!EVP_EncryptFinal_ex(evp_ctx,
133	                                 ciphertext, &ciphertext_size))
134	            throw Exception("Failed to finalize encrypting", ErrorCodes::DATA_ENCRYPTION_ERROR);
135	        if (ciphertext_size)
136	            out.write(reinterpret_cast<const char *>(ciphertext), ciphertext_size);
137	        return ciphertext_size;
138	    }
