140	    size_t decryptBlocks(EVP_CIPHER_CTX * evp_ctx, const char * data, size_t size, char * out)
141	    {
142	        const uint8_t * in = reinterpret_cast<const uint8_t *>(data);
143	        uint8_t * plaintext = reinterpret_cast<uint8_t *>(out);
144	        int plaintext_size = 0;
145	        if (!EVP_DecryptUpdate(evp_ctx, plaintext, &plaintext_size, in, size))
146	            throw Exception("Failed to decrypt", ErrorCodes::DATA_ENCRYPTION_ERROR);
147	        return plaintext_size;
148	    }
