151	    {
152	        assert((size <= kBlockSize) && (size + pad_left <= kBlockSize));
153	        uint8_t padded_data[kBlockSize] = {};
154	        memcpy(&padded_data[pad_left], data, size);
155	        size_t padded_data_size = pad_left + size;
