157	        uint8_t plaintext[kBlockSize];
158	        int plaintext_size = 0;
159	        if (!EVP_DecryptUpdate(evp_ctx, plaintext, &plaintext_size, padded_data, padded_data_size))
160	            throw Exception("Failed to decrypt", ErrorCodes::DATA_ENCRYPTION_ERROR);
161	
162	        if (!plaintext_size)
163	            return 0;
164	
165	        if (static_cast<size_t>(plaintext_size) < pad_left)
166	            throw Exception(ErrorCodes::DATA_ENCRYPTION_ERROR, "Unexpected size of decrypted data: {} < {}", plaintext_size, pad_left);
167	
168	        const uint8_t * plaintext_begin = &plaintext[pad_left];
169	        plaintext_size -= pad_left;
170	        memcpy(out, plaintext_begin, plaintext_size);
171	        return plaintext_size;
172	    }
