271	void Encryptor::encrypt(const char * data, size_t size, WriteBuffer & out)
272	{
273	    if (!size)
274	        return;
275	
276	    auto current_iv = (init_vector + blocks(offset)).toString();
277	
278	    auto evp_ctx_ptr = std::unique_ptr<EVP_CIPHER_CTX, decltype(&::EVP_CIPHER_CTX_free)>(EVP_CIPHER_CTX_new(), &EVP_CIPHER_CTX_free);
279	    auto * evp_ctx = evp_ctx_ptr.get();
280	
281	    if (!EVP_EncryptInit_ex(evp_ctx, evp_cipher, nullptr, nullptr, nullptr))
282	        throw Exception("Failed to initialize encryption context with cipher", ErrorCodes::DATA_ENCRYPTION_ERROR);
283	
284	    if (!EVP_EncryptInit_ex(evp_ctx, nullptr, nullptr,
285	                            reinterpret_cast<const uint8_t*>(key.c_str()), reinterpret_cast<const uint8_t*>(current_iv.c_str())))
286	        throw Exception("Failed to set key and IV for encryption", ErrorCodes::DATA_ENCRYPTION_ERROR);
287	
288	    size_t in_size = 0;
289	    size_t out_size = 0;
290	
291	    auto off = blockOffset(offset);
292	    if (off)
293	    {
294	        size_t in_part_size = partBlockSize(size, off);
295	        size_t out_part_size = encryptBlockWithPadding(evp_ctx, &data[in_size], in_part_size, off, out);
296	        in_size += in_part_size;
297	        out_size += out_part_size;
298	    }
299	
300	    if (in_size < size)
301	    {
302	        size_t in_part_size = size - in_size;
303	        size_t out_part_size = encryptBlocks(evp_ctx, &data[in_size], in_part_size, out);
304	        in_size += in_part_size;
305	        out_size += out_part_size;
306	    }
307	
308	    out_size += encryptFinal(evp_ctx, out);
309	
310	    if (out_size != in_size)
311	        throw Exception("Only part of the data was encrypted", ErrorCodes::DATA_ENCRYPTION_ERROR);
312	    offset += in_size;
313	}
