315	void Encryptor::decrypt(const char * data, size_t size, char * out)
316	{
317	    if (!size)
318	        return;
319	
320	    auto current_iv = (init_vector + blocks(offset)).toString();
321	
322	    auto evp_ctx_ptr = std::unique_ptr<EVP_CIPHER_CTX, decltype(&::EVP_CIPHER_CTX_free)>(EVP_CIPHER_CTX_new(), &EVP_CIPHER_CTX_free);
323	    auto * evp_ctx = evp_ctx_ptr.get();
324	
325	    if (!EVP_DecryptInit_ex(evp_ctx, evp_cipher, nullptr, nullptr, nullptr))
326	        throw Exception("Failed to initialize decryption context with cipher", ErrorCodes::DATA_ENCRYPTION_ERROR);
327	
328	    if (!EVP_DecryptInit_ex(evp_ctx, nullptr, nullptr,
329	                            reinterpret_cast<const uint8_t*>(key.c_str()), reinterpret_cast<const uint8_t*>(current_iv.c_str())))
330	        throw Exception("Failed to set key and IV for decryption", ErrorCodes::DATA_ENCRYPTION_ERROR);
331	
332	    size_t in_size = 0;
333	    size_t out_size = 0;
334	
335	    auto off = blockOffset(offset);
336	    if (off)
337	    {
338	        size_t in_part_size = partBlockSize(size, off);
339	        size_t out_part_size = decryptBlockWithPadding(evp_ctx, &data[in_size], in_part_size, off, &out[out_size]);
340	        in_size += in_part_size;
341	        out_size += out_part_size;
342	    }
343	
344	    if (in_size < size)
345	    {
346	        size_t in_part_size = size - in_size;
347	        size_t out_part_size = decryptBlocks(evp_ctx, &data[in_size], in_part_size, &out[out_size]);
348	        in_size += in_part_size;
349	        out_size += out_part_size;
350	    }
351	
352	    out_size += decryptFinal(evp_ctx, &out[out_size]);
353	
354	    if (out_size != in_size)
355	        throw Exception("Only part of the data was decrypted", ErrorCodes::DATA_ENCRYPTION_ERROR);
356	    offset += in_size;
357	}
