359	
360	void Header::read(ReadBuffer & in)
361	{
362	    constexpr size_t header_signature_size = std::size(kHeaderSignature) - 1;
363	    char signature[std::size(kHeaderSignature)] = {};
364	    in.readStrict(signature, header_signature_size);
365	    if (strcmp(signature, kHeaderSignature) != 0)
366	        throw Exception(ErrorCodes::DATA_ENCRYPTION_ERROR, "Wrong signature, this is not an encrypted file");
367	
368	    UInt16 version;
369	    readPODBinary(version, in);
370	    if (version != kHeaderCurrentVersion)
371	        throw Exception(ErrorCodes::DATA_ENCRYPTION_ERROR, "Version {} of the header is not supported", version);
372	
373	    UInt16 algorithm_u16;
374	    readPODBinary(algorithm_u16, in);
375	    algorithm = static_cast<Algorithm>(algorithm_u16);
376	
377	    readPODBinary(key_id, in);
378	    readPODBinary(key_hash, in);
379	    init_vector.read(in);
380	
381	    constexpr size_t reserved_size = kSize - header_signature_size - sizeof(version) - sizeof(algorithm_u16) - sizeof(key_id) - sizeof(key_hash) - InitVector::kSize;
382	    static_assert(reserved_size < kSize);
383	    in.ignore(reserved_size);
384	}
385	
386	void Header::write(WriteBuffer & out) const
387	{
388	    constexpr size_t header_signature_size = std::size(kHeaderSignature) - 1;
389	    out.write(kHeaderSignature, header_signature_size);
390	
391	    UInt16 version = kHeaderCurrentVersion;
392	    writePODBinary(version, out);
393	
394	    UInt16 algorithm_u16 = static_cast<UInt16>(algorithm);
395	    writePODBinary(algorithm_u16, out);
396	
397	    writePODBinary(key_id, out);
398	    writePODBinary(key_hash, out);
399	    init_vector.write(out);
400	
401	    constexpr size_t reserved_size = kSize - header_signature_size - sizeof(version) - sizeof(algorithm_u16) - sizeof(key_id) - sizeof(key_hash) - InitVector::kSize;
402	    static_assert(reserved_size < kSize);
403	    char reserved_zero_bytes[reserved_size] = {};
404	    out.write(reserved_zero_bytes, reserved_size);
405	}
